// The Automation settings page could not be saved by any organization.
//
// ── THE FAULT ─────────────────────────────────────────────────────────────
//
// `organizations.auto_generate_days_ahead` has a CHECK of 1-365 and a DEFAULT
// of 90. Two pages write it:
//
//   settings.scheduling.tsx   input max 365, validator 1-365   ✓
//   settings.automation.tsx   input max  60, validator 1-60    ✗
//
// So every organization sat above the second page's ceiling from the moment it
// was created. And settings.automation.tsx sends its ENTIRE payload on every
// save -- `autoGenerateDaysAhead` included, unconditionally -- so the whole
// mutation was rejected by Zod before it reached the server. The dunning
// ladder, the deep-clean months, the overdue reminders and all five SMS
// toggles were unsaveable, and the failure surfaced as a raw validation blob.
//
// Measured against production on 2026-08-25: 4 organizations, every one of
// them at 90.
//
// ── WHAT THIS PINS ────────────────────────────────────────────────────────
//
// Not the number. The number will change. What must hold is that the two
// pages, their two validators and the column agree — a bound enforced in four
// places drifts silently, and the symptom is a page that cannot be saved
// rather than an error naming the field.
import { describe, it, expect } from "vitest";
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dirname, "..");
const read = (p: string) => readFileSync(join(root, p), "utf8");

/** The CHECK the column actually carries, from the migration that added it. */
function columnBound(): { min: number; max: number } {
  const dir = join(root, "supabase/migrations");
  for (const f of readdirSync(dir).sort().reverse()) {
    const src = readFileSync(join(dir, f), "utf8");
    const m = /auto_generate_days_ahead[^;]*?BETWEEN\s+(\d+)\s+AND\s+(\d+)/is.exec(src);
    if (m) return { min: Number(m[1]), max: Number(m[2]) };
  }
  throw new Error("no CHECK found for auto_generate_days_ahead — this test cannot mean anything");
}

describe("both pages that write auto_generate_days_ahead agree with the column", () => {
  const bound = columnBound();

  it("finds a real bound to compare against", () => {
    expect(bound.min).toBeGreaterThan(0);
    expect(bound.max).toBeGreaterThanOrEqual(90); // the column's own DEFAULT
  });

  it("the automation validator admits everything the column does", () => {
    const src = read("src/lib/automation.functions.ts");
    const m = /autoGenerateDaysAhead:[^\n]*?\.min\((\d+)\)\.max\((\d+)\)/.exec(src);
    expect(m, "autoGenerateDaysAhead validator not found").toBeTruthy();
    expect(Number(m![2])).toBe(bound.max);
  });

  it("the automation input offers everything the column does", () => {
    // A validator that accepts 365 behind an input capped at 60 is the same
    // bug wearing a different hat.
    expect(read("src/routes/_authenticated/settings.automation.tsx")).toMatch(
      new RegExp(`max=\\{${bound.max}\\}`),
    );
  });

  it("and so does the scheduling page, which always did", () => {
    expect(read("src/routes/_authenticated/settings.scheduling.tsx")).toMatch(
      new RegExp(`max=\\{${bound.max}\\}`),
    );
  });
});
